 1	/**
 2	 * WP-007: Knowledge Handler Unit Tests
 3	 *
 4	 * 30 test cases covering all 5 REST handler functions:
 5	 * - handleListKnowledge       (7 cases)
 6	 * - handleUpdateKnowledge     (6 cases, including scope disambiguation)
 7	 * - handleDeleteKnowledge     (4 cases, including scope disambiguation)
 8	 * - handlePromoteKnowledge    (5 cases, including scope disambiguation)
 9	 * - handleMoveKnowledge       (6 cases, including scope disambiguation)
10	 * - parseKnowledgeId          (2 cases — exercised through mirror + handler calls)
11	 *
12	 * Uses real temp directories and KnowledgeStoreManager for fixture setup
13	 * (no mocks of the storage layer). Follows the pattern established in
14	 * tests/gui/api.test.ts.
15	 */
16	
17	import { describe, it, expect, beforeEach, afterEach } from 'vitest';
18	import { mkdtemp, rm } from 'fs/promises';
19	import { join } from 'path';
20	import { tmpdir } from 'os';
21	
22	import {
23	  handleListKnowledge,
24	  handleUpdateKnowledge,
25	  handleDeleteKnowledge,
26	  handlePromoteKnowledge,
27	  handleMoveKnowledge,
28	  ApiError,
29	} from '../../gui/api.js';
30	import { KnowledgeStoreManager } from '../../src/storage/knowledge-store.js';
31	import type { Insight } from '../../src/schema/knowledge.js';
32	
33	// ---------------------------------------------------------------------------
34	// Helpers
35	// ---------------------------------------------------------------------------
36	
37	/** Build a minimal valid insight input (no id). */
38	function makeInsightInput(overrides: Partial<Omit<Insight, 'id'>> = {}): Omit<Insight, 'id'> {
39	  return {
40	    scope: 'global',
41	    title: 'Default title',
42	    content: 'Default content',
43	    category: 'general',
44	    tags: [],
45	    source: 'test',
46	    created_at: '2026-01-01T00:00:00Z',
47	    confidence: 0.8,
48	    ...overrides,
49	  };
50	}
51	
52	// ---------------------------------------------------------------------------
53	// handleListKnowledge (7 cases)
54	// ---------------------------------------------------------------------------
55	
56	describe('handleListKnowledge', () => {
57	  let ledgerRoot: string;
58	  let manager: KnowledgeStoreManager;
59	
60	  beforeEach(async () => {
61	    ledgerRoot = await mkdtemp(join(tmpdir(), 'knowledge-api-list-'));
62	    manager = new KnowledgeStoreManager(ledgerRoot);
63	  });
64	
65	  afterEach(async () => {
66	    await rm(ledgerRoot, { recursive: true, force: true });
67	  });
68	
69	  it('no filters returns all insights', async () => {
70	    await manager.addInsight(makeInsightInput({ scope: 'global', title: 'Global insight' }));
71	    await manager.addInsight(
72	      makeInsightInput({ scope: 'project', project_slug: 'my-project', title: 'Project insight' })
73	    );
74	
75	    const result = await handleListKnowledge(ledgerRoot);
76	    expect(result).toHaveLength(2);
77	    const titles = result.map((i) => i.title);
78	    expect(titles).toContain('Global insight');
79	    expect(titles).toContain('Project insight');
80	  });

 81	
 82	  it('scope:global returns only global', async () => {
 83	    await manager.addInsight(makeInsightInput({ scope: 'global', title: 'Global' }));
 84	    await manager.addInsight(
 85	      makeInsightInput({ scope: 'project', project_slug: 'proj', title: 'Project' })
 86	    );
 87	
 88	    const result = await handleListKnowledge(ledgerRoot, { scope: 'global' });
 89	    expect(result).toHaveLength(1);
 90	    expect(result[0]!.scope).toBe('global');
 91	    expect(result[0]!.title).toBe('Global');
 92	  });
 93	
 94	  it('scope:project + project_slug filters to one project', async () => {
 95	    await manager.addInsight(makeInsightInput({ scope: 'global', title: 'Global' }));
 96	    await manager.addInsight(
 97	      makeInsightInput({ scope: 'project', project_slug: 'alpha', title: 'Alpha insight' })
 98	    );
 99	    await manager.addInsight(
100	      makeInsightInput({ scope: 'project', project_slug: 'beta', title: 'Beta insight' })
101	    );
102	
103	    const result = await handleListKnowledge(ledgerRoot, {
104	      scope: 'project',
105	      project_slug: 'alpha',
106	    });
107	    expect(result).toHaveLength(1);
108	    expect(result[0]!.title).toBe('Alpha insight');
109	    expect(result[0]!.project_slug).toBe('alpha');
110	  });
111	
112	  it('category filter', async () => {
113	    await manager.addInsight(makeInsightInput({ title: 'Best practice A', category: 'best-practice' }));
114	    await manager.addInsight(makeInsightInput({ title: 'Pattern', category: 'pattern' }));
115	    await manager.addInsight(makeInsightInput({ title: 'Best practice B', category: 'best-practice' }));
116	
117	    const result = await handleListKnowledge(ledgerRoot, { category: 'best-practice' });
118	    expect(result).toHaveLength(2);
119	    expect(result.every((i) => i.category === 'best-practice')).toBe(true);
120	  });
121	
122	  it('tags filter (comma-separated string parsed correctly)', async () => {
123	    await manager.addInsight(
124	      makeInsightInput({ title: 'Node insight', tags: ['node', 'backend'] })
125	    );
126	    await manager.addInsight(
127	      makeInsightInput({ title: 'Frontend insight', tags: ['frontend', 'css'] })
128	    );
129	    await manager.addInsight(
130	      makeInsightInput({ title: 'Full stack', tags: ['node', 'frontend'] })
131	    );
132	
133	    // Only insights that have BOTH 'node' and 'backend'
134	    const result = await handleListKnowledge(ledgerRoot, { tags: 'node,backend' });
135	    expect(result).toHaveLength(1);
136	    expect(result[0]!.title).toBe('Node insight');
137	  });
138	
139	  it('query triggers searchInsights, returns text matches', async () => {
140	    await manager.addInsight(
141	      makeInsightInput({ title: 'Atomic writes are important', content: 'Use atomic writes.' })
142	    );
143	    await manager.addInsight(
144	      makeInsightInput({ title: 'File locking', content: 'Use proper file locks.' })
145	    );
146	    await manager.addInsight(
147	      makeInsightInput({ title: 'Indexing strategy', tags: ['atomic', 'index'] })
148	    );
149	
150	    const result = await handleListKnowledge(ledgerRoot, { query: 'atomic' });
151	    expect(result.length).toBeGreaterThanOrEqual(1);
152	    const titles = result.map((i) => i.title);
153	    expect(titles).toContain('Atomic writes are important');
154	  });
155	
156	  it('empty store returns empty array', async () => {
157	    const result = await handleListKnowledge(ledgerRoot);
158	    expect(result).toEqual([]);
159	  });
160	});

161	
162	// ---------------------------------------------------------------------------
163	// handleUpdateKnowledge (6 cases)
164	// ---------------------------------------------------------------------------
165	
166	describe('handleUpdateKnowledge', () => {
167	  let ledgerRoot: string;
168	  let manager: KnowledgeStoreManager;
169	
170	  beforeEach(async () => {
171	    ledgerRoot = await mkdtemp(join(tmpdir(), 'knowledge-api-update-'));
172	    manager = new KnowledgeStoreManager(ledgerRoot);
173	  });
174	
175	  afterEach(async () => {
176	    await rm(ledgerRoot, { recursive: true, force: true });
177	  });
178	
179	  it('updates title and returns updated insight', async () => {
180	    const created = await manager.addInsight(makeInsightInput({ title: 'Original title' }));
181	
182	    const updated = await handleUpdateKnowledge(ledgerRoot, String(created.id), {
183	      scope: 'global',
184	      title: 'Updated title',
185	    });
186	
187	    expect(updated.id).toBe(created.id);
188	    expect(updated.title).toBe('Updated title');
189	    expect(updated.content).toBe('Default content');
190	  });
191	
192	  it('clears superseded_by when null is passed', async () => {
193	    const created = await manager.addInsight(
194	      makeInsightInput({ title: 'Superseded', superseded_by: 99 })
195	    );
196	    expect(created.superseded_by).toBe(99);
197	
198	    const updated = await handleUpdateKnowledge(ledgerRoot, String(created.id), {
199	      scope: 'global',
200	      superseded_by: null,
201	    });
202	
203	    expect(updated.superseded_by).toBeUndefined();
204	  });
205	
206	  it('throws NOT_FOUND for unknown id', async () => {
207	    await expect(
208	      handleUpdateKnowledge(ledgerRoot, '99999', { scope: 'global', title: 'x' })
209	    ).rejects.toMatchObject({ code: 'NOT_FOUND' });
210	  });
211	
212	  it('throws VALIDATION_ERROR for non-integer id', async () => {
213	    await expect(
214	      handleUpdateKnowledge(ledgerRoot, 'abc', { scope: 'global', title: 'x' })
215	    ).rejects.toMatchObject({ code: 'VALIDATION_ERROR' });
216	  });
217	
218	  it('throws VALIDATION_ERROR for extra body fields', async () => {
219	    await expect(
220	      handleUpdateKnowledge(ledgerRoot, '1', { scope: 'global', unknownField: 'bad' })

221	    ).rejects.toMatchObject({ code: 'VALIDATION_ERROR' });
222	  });
223	
224	  it('updates insight in global store, not same-id insight in project store (scope disambiguation)', async () => {
225	    // Both stores start at next_id=1, so their first insight will have id=1
226	    const globalInsight = await manager.addInsight(
227	      makeInsightInput({ scope: 'global', title: 'Global id=1' })
228	    );
229	    const projectInsight = await manager.addInsight(
230	      makeInsightInput({ scope: 'project', project_slug: 'proj-a', title: 'Project id=1' })
231	    );
232	
233	    expect(globalInsight.id).toBe(1);
234	    expect(projectInsight.id).toBe(1);
235	
236	    // Update only the global-scoped insight
237	    const updated = await handleUpdateKnowledge(ledgerRoot, '1', {
238	      scope: 'global',
239	      title: 'Updated global',
240	    });
241	
242	    expect(updated.title).toBe('Updated global');
243	    expect(updated.scope).toBe('global');
244	
245	    // Verify project insight is unchanged
246	    const projectInsights = await manager.listInsights({
247	      scope: 'project',
248	      project_slug: 'proj-a',
249	    });
250	    expect(projectInsights[0]!.title).toBe('Project id=1');
251	  });
252	});
253	
254	// ---------------------------------------------------------------------------
255	// handleDeleteKnowledge (4 cases)
256	// ---------------------------------------------------------------------------
257	
258	describe('handleDeleteKnowledge', () => {
259	  let ledgerRoot: string;
260	  let manager: KnowledgeStoreManager;
261	
262	  beforeEach(async () => {
263	    ledgerRoot = await mkdtemp(join(tmpdir(), 'knowledge-api-delete-'));
264	    manager = new KnowledgeStoreManager(ledgerRoot);
265	  });
266	
267	  afterEach(async () => {
268	    await rm(ledgerRoot, { recursive: true, force: true });
269	  });
270	
