272	    const created = await manager.addInsight(makeInsightInput({ title: 'To delete' }));
273	
274	    const result = await handleDeleteKnowledge(ledgerRoot, String(created.id), 'global');
275	
276	    expect(result).toBeNull();
277	
278	    const remaining = await manager.listInsights({ scope: 'global' });
279	    expect(remaining).toHaveLength(0);
280	  });
281	
282	  it('throws NOT_FOUND for unknown id', async () => {
283	    await expect(
284	      handleDeleteKnowledge(ledgerRoot, '99999', 'global')
285	    ).rejects.toMatchObject({ code: 'NOT_FOUND' });
286	  });
287	
288	  it('throws VALIDATION_ERROR for id=0', async () => {
289	    await expect(
290	      handleDeleteKnowledge(ledgerRoot, '0', 'global')
291	    ).rejects.toMatchObject({ code: 'VALIDATION_ERROR' });
292	  });
293	
294	  it('deletes insight in project store, not same-id insight in global store (scope disambiguation)', async () => {
295	    // Both stores start at next_id=1, so their first insight will have id=1
296	    const globalInsight = await manager.addInsight(
297	      makeInsightInput({ scope: 'global', title: 'Global id=1' })
298	    );
299	    const projectInsight = await manager.addInsight(
