307	    const result = await handleDeleteKnowledge(ledgerRoot, '1', 'project', 'proj-a');
308	    expect(result).toBeNull();
309	
310	    // Project insight is gone
311	    const projectInsights = await manager.listInsights({
312	      scope: 'project',
